#include <stdlib.h>
#include <string.h>
#include <omp.h>

#ifdef __AVX512F__
typedef float vf __attribute__((vector_size(64)));
#define VW 16
#define MR 8
#define KC 256
#define MCP0 12   /* row panels per item (96 rows) */
#define NCP0 4    /* column panels per item (128 cols) */
#define ROWS(X) X(0) X(1) X(2) X(3) X(4) X(5) X(6) X(7)
#else
typedef float vf __attribute__((vector_size(32)));
#define VW 8
#define MR 6
#define KC 384
#define MCP0 12   /* 72 rows */
#define NCP0 8    /* 128 cols */
#define ROWS(X) X(0) X(1) X(2) X(3) X(4) X(5)
#endif

#define NR (2 * VW)

static inline vf ldu(const float *p) { vf v; memcpy(&v, p, sizeof(v)); return v; }
static inline void stu(float *p, vf v) { memcpy(p, &v, sizeof(v)); }

#define DECL(i) vf c##i##_0 = {0}, c##i##_1 = {0};
#define PFC(i) { float *q_ = c + (size_t)((i) < mr ? (i) : 0) * ldc; \
                 __builtin_prefetch(q_, 1, 3); __builtin_prefetch(q_ + NR - 1, 1, 3); }
#define STEP(i) { vf a_ = (vf){0} + ap[i]; c##i##_0 += a_ * b0; c##i##_1 += a_ * b1; }
#define STROW(i) if ((i) < mr) { float *cp = c + (size_t)(i) * ldc; \
    if (accum) { stu(cp, ldu(cp) + c##i##_0); stu(cp + VW, ldu(cp + VW) + c##i##_1); } \
    else { stu(cp, c##i##_0); stu(cp + VW, c##i##_1); } }
#define STTMP(i) stu(&tmp[i][0], c##i##_0); stu(&tmp[i][VW], c##i##_1);

static inline __attribute__((always_inline))
void kernel(int kc, const float *restrict a, const float *restrict b,
            float *restrict c, int ldc, int mr, int nr, const int accum)
{
    ROWS(DECL)
    ROWS(PFC)

    #pragma GCC unroll 2
    for (int k = 0; k < kc; k++) {
        vf b0 = *(const vf *)(b + NR * k);
        vf b1 = *(const vf *)(b + NR * k + VW);
        const float *ap = a + MR * k;
        ROWS(STEP)
    }

    if (nr == NR) {
        ROWS(STROW)
    } else {
        float tmp[MR][NR] __attribute__((aligned(64)));
        ROWS(STTMP)
        for (int i = 0; i < mr; i++) {
            float *cp = c + (size_t)i * ldc;
            if (accum)
                for (int j = 0; j < nr; j++) cp[j] += tmp[i][j];
            else
                for (int j = 0; j < nr; j++) cp[j] = tmp[i][j];
        }
    }
}

static float *g_Abuf, *g_Bbuf;
static size_t g_capA, g_capB;

static float *grow(float *p, size_t *cap, size_t need)
{
    if (need <= *cap && p) return p;
    free(p);
    size_t bytes = (need * sizeof(float) + 63) & ~(size_t)63;
    if (bytes == 0) bytes = 64;
    p = (float *)aligned_alloc(64, bytes);
    *cap = need;
    return p;
}

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;

    int rp = (n + MR - 1) / MR;
    int cpn = (n + NR - 1) / NR;
    /* per K block pc: A block at pc*rp*MR, panel ip at ip*kc*MR (same for B) */
    size_t szA = (size_t)rp * MR * n;
    size_t szB = (size_t)cpn * NR * n;
    g_Abuf = grow(g_Abuf, &g_capA, szA);
    g_Bbuf = grow(g_Bbuf, &g_capB, szB);
    float *Abuf = g_Abuf, *Bbuf = g_Bbuf;

    /* size work items so there are enough of them to balance across threads */
    int nt = omp_get_max_threads();
    int mcp = MCP0, ncp = NCP0;
    for (;;) {
        long items = (long)((rp + mcp - 1) / mcp) * ((cpn + ncp - 1) / ncp);
        if (items >= 3L * nt) break;
        if (mcp > 2) mcp = (mcp + 1) / 2;
        else if (ncp > 2) ncp = (ncp + 1) / 2;
        else break;
    }
    int nib = (rp + mcp - 1) / mcp;
    int njb = (cpn + ncp - 1) / ncp;
    int nitems = nib * njb;

    #pragma omp parallel
    {
        /* pack all of A */
        #pragma omp for schedule(static) nowait
        for (int ip = 0; ip < rp; ip++) {
            int i0 = ip * MR;
            int mr = n - i0 < MR ? n - i0 : MR;
            for (int pc = 0; pc < n; pc += KC) {
                int kc = n - pc < KC ? n - pc : KC;
                float *dst = Abuf + (size_t)pc * rp * MR + (size_t)ip * kc * MR;
                const float *src = A + (size_t)i0 * n + pc;
                if (mr == MR) {
                    for (int k = 0; k < kc; k++) {
                        float *d = dst + k * MR;
                        #pragma GCC unroll 16
                        for (int ii = 0; ii < MR; ii++) d[ii] = src[(size_t)ii * n + k];
                    }
                } else {
                    for (int k = 0; k < kc; k++) {
                        float *d = dst + k * MR;
                        int ii = 0;
                        for (; ii < mr; ii++) d[ii] = src[(size_t)ii * n + k];
                        for (; ii < MR; ii++) d[ii] = 0.0f;
                    }
                }
            }
        }

        /* pack all of B; the barrier at the end also covers the A pack */
        #pragma omp for schedule(static)
        for (int jp = 0; jp < cpn; jp++) {
            int j0 = jp * NR;
            int nr = n - j0 < NR ? n - j0 : NR;
            for (int pc = 0; pc < n; pc += KC) {
                int kc = n - pc < KC ? n - pc : KC;
                float *dst = Bbuf + (size_t)pc * cpn * NR + (size_t)jp * kc * NR;
                if (nr == NR) {
                    for (int k = 0; k < kc; k++)
                        memcpy(dst + k * NR, B + (size_t)(pc + k) * n + j0, NR * sizeof(float));
                } else {
                    for (int k = 0; k < kc; k++) {
                        const float *src = B + (size_t)(pc + k) * n + j0;
                        float *d = dst + k * NR;
                        int j = 0;
                        for (; j < nr; j++) d[j] = src[j];
                        for (; j < NR; j++) d[j] = 0.0f;
                    }
                }
            }
        }

        /* each item owns a tile of C over the full K range; consecutive items
           share a B column block */
        #pragma omp for schedule(dynamic, 1) nowait
        for (int it = 0; it < nitems; it++) {
            int jb = it / nib, ib = it % nib;
            int p0 = ib * mcp, p1 = p0 + mcp < rp ? p0 + mcp : rp;
            int q0 = jb * ncp, q1 = q0 + ncp < cpn ? q0 + ncp : cpn;

            for (int pc = 0; pc < n; pc += KC) {
                int kc = n - pc < KC ? n - pc : KC;
                const float *Ap = Abuf + (size_t)pc * rp * MR;
                const float *Bp = Bbuf + (size_t)pc * cpn * NR;

                for (int jp = q0; jp < q1; jp++) {
                    int j = jp * NR;
                    int nr = n - j < NR ? n - j : NR;
                    const float *bp = Bp + (size_t)jp * kc * NR;
                    for (int ip = p0; ip < p1; ip++) {
                        int i = ip * MR;
                        int mr = n - i < MR ? n - i : MR;
                        const float *ap = Ap + (size_t)ip * kc * MR;
                        float *cc = C + (size_t)i * n + j;
                        if (pc > 0) kernel(kc, ap, bp, cc, n, mr, nr, 1);
                        else        kernel(kc, ap, bp, cc, n, mr, nr, 0);
                    }
                }
            }
        }
    }
}
